  {"id": "strider-2", "title": "Strider 2", "project": "STRIDER-2-Recompiled", "console": "ps1", "year": 2000, "developer": "Capcom", "genre": "Action", "stage": "development", "quality": "C", "toolchain": "PSXRecomp", "team": "strider973", "repo": "https://github.com/strider973/STRIDER-2-Recompiled", "website": null, "version": "v0.1.2", "versionDate": "2026-08-29", "started": "2026-08-24", "updated": "2026-08-29", "stars": 39, "features": [], "ai": false, "summary": "Static recompilation of Strider 2 (SLUS-01163) built on psxrecomp and recomp-ui.", "requires": "A Strider 2 disc image (PS1, SLUS-01163) and the SCPH1001.BIN BIOS.", "cover": "assets/covers/strider-2.webp", "coverFrom": "libretro:Strider 2 (USA)", "platforms": ["windows", "linux", "macos"], "platformsFrom": "release", "platformsTag": "v0.1.2", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 2, "visitsWeek": 0},
  {"id": "super-mario-3d-world-decomp", "title": "Super Mario 3D World + Bowser's Fury", "project": "3DWDecomp", "console": "switch", "year": 2021, "developer": "Nintendo EPD", "genre": "Platformer", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "shibbo", "repo": "https://github.com/shibbo/3DWDecomp", "website": null, "version": null, "versionDate": null, "started": "2026-09-08", "updated": "2026-10-18", "stars": 24, "features": [], "ai": true, "summary": "An AI-driven matching decompilation with human review: AI agents do much of the reconstruction and matching, and shibbo directs and checks the work. 63.8% of the code (51,935 of 65,185 functions) matched as of October 17, 2026, as a test of how far that approach takes one person. No playable build.", "requires": "No build to play; it rebuilds the game's code rather than porting it.", "inputFrom": "manual", "modManagerFrom": "manual", "coverFrom": "wikipedia:Super Mario 3D World", "cover": "assets/covers/super-mario-3d-world-decomp.webp", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "super-mario-3d-world-redcarpet", "title": "Super Mario 3D World + Bowser's Fury", "project": "RedCarpet-S", "console": "switch", "year": 2021, "developer": "Nintendo EPD", "genre": "Platformer", "stage": "abandoned", "quality": "D", "toolchain": "Decompilation", "team": "fruityloops1", "repo": "https://github.com/fruityloops1/RedCarpet-S", "website": null, "version": null, "versionDate": null, "started": "2023-03-17", "updated": "2024-10-15", "stars": 29, "features": [], "ai": false, "summary": "An earlier decompilation of version 1.1 (RedCarpet is the game's internal name). It has had no commits since October 2024; shibbo's 3DWDecomp is the active project for this game.", "requires": "No build to play. It worked from version 1.1.", "inputFrom": "manual", "modManagerFrom": "manual", "coverFrom": "wikipedia:Super Mario 3D World", "cover": "assets/covers/super-mario-3d-world-redcarpet.webp", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "super-mario-bros-wonder-recomp", "title": "Super Mario Bros. Wonder", "project": "Super Mario Bros. Wonder Recomp", "console": "switch", "year": 2023, "developer": "Nintendo EPD", "genre": "Platformer", "stage": "development", "quality": "C", "toolchain": "Custom", "team": "BelmanteGu", "repo": "https://github.com/BelmanteGu/SuperMarioWonderRecomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-14", "updated": "2026-10-18", "stars": 270, "features": ["widescreen", "keyboard"], "ai": true, "summary": "A static recompilation of version 1.0.0 for Apple silicon Macs, Windows, Linux and Android: the game's AArch64 code becomes C++, and its calls to NVN, Nintendo's graphics API, run on Vulkan (MoltenVK on the Mac), with every shader translated ahead of time. The title, file and character select, the opening, the world map and course 1-1 run at 60 fps, with an optional ultrawide mode that shows more of the level. Still early: Windows can crash after character select, and Android has rendering and memory issues. No release yet; you build it yourself, or an APK for Android. Most of the code was written with AI (Claude) under the author's direction.", "requires": "Your own dump of Super Mario Bros. Wonder 1.0.0 (base game, no update) with your own keys and firmware, and a Vulkan 1.3 graphics card (MoltenVK on an Apple silicon Mac). There's no download: you build it with clang, CMake and the Vulkan SDK.", "inputFrom": "manual", "modManagerFrom": "manual", "platforms": ["windows", "linux", "macos", "android"], "platformsFrom": "manual", "platformsTag": null, "cover": "assets/covers/super-mario-bros-wonder-recomp.webp", "coverFrom": "wikipedia:Super Mario Bros. Wonder", "visitsWeek": 0},
  {"id": "super-mario-galaxy", "title": "Super Mario Galaxy", "project": "Nebula", "console": "wii", "year": 2007, "developer": "Nintendo EAD", "genre": "Platformer", "stage": "released", "quality": "B", "toolchain": "Custom", "team": "keepvaibin", "repo": "https://github.com/keepvaibin/nebula", "website": null, "version": "v1.0.1", "versionDate": "2026-10-16", "started": "2026-10-06", "updated": "2026-10-16", "stars": 225, "features": ["widescreen", "keyboard-mouse"], "ai": true, "summary": "Nebula: a static recompilation of Super Mario Galaxy for Windows, with macOS and Android planned. The installer translates the game’s PowerPC code to C++ and compiles it on your PC from your own copy, so the download contains nothing from Nintendo; the runtime renders with Direct3D 12. It supports 4:3 to 32:9, internal resolution up to 16x, keyboard and mouse, Xbox controllers, and the Switch and Switch 2 Pro Controllers, which aim with the gyro. It’s playable from the start, but the author still calls it a work in progress: some areas drop below 60 fps on weaker hardware, and bugs remain.", "requires": "Your own copy of the US version (RMGE01, revision 0) as an ISO, RVZ, or extracted folder, plus 64-bit Windows 10 or 11, a Direct3D 12 graphics card, and an internet connection for the first install.", "cover": "assets/covers/super-mario-galaxy.webp", "coverFrom": "libretro:Super Mario Galaxy (USA)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v1.0.1", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 83, "visitsWeek": 10},
  {"id": "super-mario-odyssey-decomp", "title": "Super Mario Odyssey", "project": "OdysseyDecomp", "console": "switch", "year": 2017, "developer": "Nintendo EPD", "genre": "Platformer", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "MonsterDruide1", "repo": "https://github.com/MonsterDruide1/OdysseyDecomp", "website": null, "version": null, "versionDate": null, "started": "2021-07-12", "updated": "2026-10-12", "stars": 473, "features": [], "ai": false, "summary": "A matching decompilation of version 1.0.0 that recreates the game's source code from scratch: 25.6% matched as of October 17, 2026, with tools to check the code against every version. The team says plainly that it won't produce a playable game; SMO Recomp is the one that runs.", "requires": "No build to play. Contributors need version 1.0.0, dumped from their own copy.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/super-mario-odyssey-decomp.webp", "coverFrom": "wikipedia:Super Mario Odyssey", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "super-mario-odyssey-recomp", "title": "Super Mario Odyssey", "project": "smo-recomp", "console": "switch", "year": 2017, "developer": "Nintendo EPD", "genre": "Platformer", "stage": "development", "quality": "C", "toolchain": "Custom", "team": "Coz-0", "repo": "https://github.com/Coz-0/smo-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-16", "updated": "2026-10-18", "stars": 4, "features": [], "ai": true, "summary": "A static recompilation of version 1.0.0 into a native Windows program. It boots to the file select, and a scripted run plays from the prologue through Cap Kingdom into Top-Hat Tower, up to Mario's first capture, with the game's own audio, its videos and a steady 60 fps. No release yet. Most of the code was written by AI agents (Claude) under the maintainer's direction.", "requires": "Your own dump of Super Mario Odyssey version 1.0.0, Windows 10 or 11 and a Vulkan 1.3 graphics card. There's no download: you build it with LLVM/clang 9, the Visual Studio 2019 Build Tools and the Vulkan SDK.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/super-mario-odyssey-recomp.webp", "coverFrom": "wikipedia:Super Mario Odyssey", "platforms": ["windows"], "platformsFrom": "readme", "platformsTag": null, "visitsWeek": 2},
  {"id": "super-mario-strikers", "title": "Super Mario Strikers", "project": "Strikers", "console": "gamecube", "year": 2005, "developer": "Next Level Games", "genre": "Sports", "stage": "released", "quality": "A", "toolchain": "Decompilation", "team": "new-coke", "repo": "https://github.com/new-coke/strikers", "website": null, "version": "v1.3.0", "versionDate": "2026-09-22", "started": "2026-09-10", "updated": "2026-10-04", "stars": 338, "features": ["widescreen", "high-fps", "steam-deck", "keyboard"], "ai": false, "summary": "A native port built from decompiled code for Windows, Linux, macOS, Steam Deck and Switch, with Metal, Vulkan and Direct3D 12 through Aurora. Adds widescreen and ultrawide with a wider view of the pitch, high frame rates and custom texture packs.", "requires": "Your own Super Mario Strikers disc image (GameCube).", "cover": "assets/covers/super-mario-strikers.webp", "coverFrom": "libretro:Super Mario Strikers (USA)", "platforms": ["windows", "linux", "macos", "switch"], "platformsFrom": "release", "platformsTag": "v1.3.0", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 8, "visitsWeek": 0},
  {"id": "super-mario-strikers-recomp", "title": "Super Mario Strikers", "project": "StrikersRecomp", "console": "gamecube", "year": 2005, "developer": "Next Level Games", "genre": "Sports", "stage": "development", "quality": "C", "toolchain": "DolRecomp", "team": "aharonahdoot", "repo": "https://github.com/aharonahdoot/StrikersRecomp", "website": null, "version": "v0.1.0", "versionDate": "2026-07-08", "started": "2026-07-08", "updated": "2026-07-21", "stars": 8, "features": [], "ai": false, "summary": "The worked example for the RecompCore and GXRuntime toolkits: game-specific glue that turns your disc into recompiled native code. Tested on macOS, and quiet since July 2026. A decompilation-based port of the same game is listed separately.", "requires": "Your own Super Mario Strikers disc image (GameCube, NTSC, G4QE01).", "cover": "assets/covers/super-mario-strikers-recomp.webp", "coverFrom": "libretro:Super Mario Strikers (USA)", "platforms": ["macos"], "platformsFrom": "readme", "platformsTag": null, "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 0, "visitsWeek": 0},
  {"id": "super-mario-sunshine", "title": "Super Mario Sunshine", "project": "sms-port", "console": "gamecube", "year": 2002, "developer": "Nintendo EAD", "genre": "Platformer", "stage": "beta", "quality": "B", "toolchain": "Decompilation", "team": "chasem-dev", "repo": "https://github.com/chasem-dev/sms-pc-port", "website": null, "version": "hd-cutscenes-ai-v1", "versionDate": "2026-10-03", "started": "2026-09-24", "updated": "2026-10-18", "stars": 148, "features": ["launcher", "keyboard"], "ai": false, "summary": "A native port built from the Super Mario Sunshine decompilation. It plays on Linux and macOS (Intel, or Apple silicon through Rosetta 2); Windows builds boot under Wine. A separate launcher sets it up from your disc.", "requires": "Your own Super Mario Sunshine disc image (GameCube, North America, GMSE01).", "cover": "assets/covers/super-mario-sunshine.webp", "coverFrom": "libretro:Super Mario Sunshine (USA)", "platforms": ["linux", "macos"], "platformsFrom": "manual", "platformsTag": null, "inputFrom": "manual", "modManagerFrom": "none", "starsWeek": 8, "visitsWeek": 0},
  {"id": "super-mario-sunshine-sunpad", "title": "Super Mario Sunshine", "project": "SunPad", "console": "gamecube", "year": 2002, "developer": "Nintendo EAD", "genre": "Platformer", "stage": "beta", "quality": "B", "toolchain": "DolRecomp", "team": "chrissotraidis", "repo": "https://github.com/chrissotraidis/sunpad", "website": null, "version": "v0.2.1", "versionDate": "2026-10-04", "started": "2026-08-05", "updated": "2026-10-13", "stars": 187, "features": ["keyboard"], "ai": true, "summary": "Ahead-of-time recompilation for iPhone, iPad, Apple silicon Macs and (experimentally) Apple TV, built on ModernGekko and DolRecomp with Metal rendering, touch and controller support.", "requires": "Your own Super Mario Sunshine disc image (GameCube).", "cover": "assets/covers/super-mario-sunshine-sunpad.webp", "coverFrom": "libretro:Super Mario Sunshine (USA)", "platforms": ["macos"], "platformsFrom": "manual", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 3, "visitsWeek": 0},
  {"id": "super-smash-bros-64", "title": "Super Smash Bros.", "project": "smash64r", "console": "n64", "year": 1999, "developer": "HAL Laboratory", "genre": "Fighting", "stage": "development", "quality": "D", "toolchain": "N64Recomp", "team": "zestydevy", "repo": "https://github.com/zestydevy/smash64r", "website": null, "version": null, "versionDate": null, "started": "2024-10-30", "updated": "2025-05-05", "stars": 66, "features": ["keyboard"], "ai": false, "summary": "Recompilation of the original Super Smash Bros., in active development on the dev branch. No release yet.", "requires": "A Super Smash Bros. ROM (N64, US version).", "cover": "assets/covers/super-smash-bros-64.webp", "coverFrom": "libretro:Super Smash Bros. (USA)", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "inputFrom": "manual", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "melee-gd", "title": "Super Smash Bros. Melee", "project": "GD's Melee", "console": "gamecube", "year": 2001, "developer": "HAL Laboratory", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "Decompilation", "team": "GurekamDhillon", "repo": "https://github.com/GurekamDhillon/gd-melee-workspace", "website": null, "version": "v0.3.0", "versionDate": "2026-10-15", "started": "2026-09-20", "updated": "2026-10-15", "stars": 17, "features": ["mods", "multiplayer", "online", "launcher"], "ai": false, "summary": "A native port for Windows and Linux built from the matching Melee decompilation. It plays online with rollback netcode, room codes and a competitive lobby (Windows and Linux players can face each other), renders in HD, runs m-ex mod discs and loose mods with an in-game browser for SSBM Nucleus mods, and can be scripted in Lua. Adds the Envoy roguelite mode, solo or co-op. A public test build, so expect rough edges.", "requires": "Your own Super Smash Bros. Melee disc image (GameCube, NTSC 1.02, GALE01); mod discs work too.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/melee-gd.webp", "coverFrom": "libretro:Super Smash Bros. Melee (USA)", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v0.3.0"},
  {"id": "melee-macos-recomp", "title": "Super Smash Bros. Melee", "project": "melee-macos-recomp", "console": "gamecube", "year": 2001, "developer": "HAL Laboratory", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "DolRecomp", "team": "McDandle", "repo": "https://github.com/McDandle/melee-macos-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-09-08", "updated": "2026-09-08", "stars": 1, "features": ["keyboard"], "ai": false, "summary": "An experimental Apple silicon Mac port: DolRecomp to native ARM64, ModernGekko with Metal, 1x to 6x internal resolution, at about 60 fps. Source only.", "requires": "Your own Melee disc image (GameCube, USA revision 2) and an Apple silicon Mac on macOS 14 or newer.", "cover": "assets/covers/melee-macos-recomp.webp", "coverFrom": "libretro:Super Smash Bros. Melee (USA)", "platforms": ["macos"], "platformsFrom": "readme", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 0, "visitsWeek": 0},
  {"id": "melee-pc", "title": "Super Smash Bros. Melee", "project": "melee-pc", "console": "gamecube", "year": 2001, "developer": "HAL Laboratory", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "Decompilation", "team": "999sian", "repo": "https://github.com/999sian/melee-pc", "website": null, "version": "v0.3.1-beta", "versionDate": "2026-10-14", "started": "2026-09-14", "updated": "2026-10-17", "stars": 488, "features": ["online", "multiplayer", "keyboard"], "ai": false, "summary": "A native port built from the doldecomp/melee decompilation on Aurora and SDL3, for Windows, Linux, macOS, Android and iOS. Every mode boots and plays; LAN, friend codes and ranked matchmaking are in, with rollback netcode still in development.", "requires": "Your own Melee disc image (GameCube, NTSC-U 1.02).", "cover": "assets/covers/melee-pc.webp", "coverFrom": "libretro:Super Smash Bros. Melee (USA)", "platforms": ["windows", "linux", "macos", "android"], "platformsFrom": "release", "platformsTag": "v0.3.1-beta", "inputFrom": "manual", "modManagerFrom": "none", "starsWeek": 18, "visitsWeek": 3},
  {"id": "melee-unlocked", "title": "Super Smash Bros. Melee", "project": "Melee Unlocked", "console": "gamecube", "year": 2001, "developer": "HAL Laboratory", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "Decompilation", "team": "Hero88go", "repo": "https://github.com/Hero88go/melee-unlocked", "website": null, "version": "v0.8.99", "versionDate": "2026-10-16", "started": "2026-09-12", "updated": "2026-10-17", "stars": 122, "features": ["widescreen", "high-fps", "online", "mods", "keyboard"], "ai": true, "summary": "A Windows build with two engines: a source port compiled from the decompilation, and a static recomp of the retail code. Adds Slippi online play against Slippi Dolphin, an unlocked frame rate, 16:9 and mod support.", "requires": "Your own Melee disc image (GameCube, NTSC 1.02).", "cover": "assets/covers/melee-unlocked.webp", "coverFrom": "libretro:Super Smash Bros. Melee (USA)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.8.99", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 7, "visitsWeek": 0},
  {"id": "smash-ultimate-decomp", "title": "Super Smash Bros. Ultimate", "project": "ssbu-decomp", "console": "switch", "year": 2018, "developer": "Bandai Namco Studios", "genre": "Fighting", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "sbergeron42", "repo": "https://github.com/sbergeron42/ssbu-decomp", "website": null, "version": null, "versionDate": null, "started": "2026-03-30", "updated": "2026-04-13", "stars": 18, "features": [], "ai": false, "summary": "A matching decompilation of patch 13.0.4, the final version: 14,156 of 39,635 functions decompiled and 26.2% verified byte for byte, but only 1.8% of the code by size, since the matched functions are mostly small ones. No commits since April 2026. No playable build; SSBU Recomp is the one that runs.", "requires": "No build to play. It works from patch 13.0.4.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/smash-ultimate-decomp.webp", "coverFrom": "wikipedia:Super Smash Bros. Ultimate", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "smash-ultimate-recomp", "title": "Super Smash Bros. Ultimate", "project": "ssbu-recomp", "console": "switch", "year": 2018, "developer": "Bandai Namco Studios", "genre": "Fighting", "stage": "development", "quality": "C", "toolchain": "Custom", "team": "Denkishi", "repo": "https://github.com/Denkishi/ssbu-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-12", "updated": "2026-10-16", "stars": 203, "features": ["mods"], "ai": true, "summary": "A static recompilation of version 13.0.4 into a native Windows program with its own runtime and Vulkan renderer. Early and playable in parts: the opening movie, title and menus work. It also turns the fighters' scripts back into readable code (95% of their animation scripts so far) and can add new fighters as copies of existing ones. Linux and the Steam Deck aren't started, and there's no release yet.", "requires": "Your own dump of Super Smash Bros. Ultimate updated to 13.0.4, and Windows. No download yet: you build it yourself.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/smash-ultimate-recomp.webp", "coverFrom": "wikipedia:Super Smash Bros. Ultimate", "platforms": ["windows"], "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "smash-ultimate-windowsmash", "title": "Super Smash Bros. Ultimate", "project": "WindowSmash", "console": "switch", "year": 2018, "developer": "Bandai Namco Studios", "genre": "Fighting", "stage": "development", "quality": "C", "toolchain": "Custom", "team": "SNO2207", "repo": "https://github.com/SNO2207/WindowSmash", "website": null, "version": "v0.1.0-alpha.1", "versionDate": "2026-10-18", "started": "2026-10-18", "updated": "2026-10-18", "stars": 103, "features": ["online", "keyboard"], "ai": false, "summary": "A static recompilation of version 11.0.0 for Windows: the game's AArch64 code is translated to C ahead of time and runs on its own runtime, with a Direct3D 11 renderer that translates the Switch's shaders and caches them. A prebuilt runtime is in the releases, so you only point it at your own game files; later versions such as 13.0.5 can be built from your own update. Online play carries the game's Local Wireless mode over a relay, through a public lobby or private rooms. One player per PC for now, and full two-PC matches and the whole roster haven't been fully checked. An experimental Linux build runs through DXVK.", "requires": "Your own Super Smash Bros. Ultimate RomFS (version 11.0.0, or a later update you build yourself) and the Switch's firmware fonts, Windows 10 or 11, a processor with AVX2, FMA and F16C, and a Direct3D 11 graphics card.", "inputFrom": "manual", "modManagerFrom": "manual", "pick": true, "pickNote": "The only one you can download and play: a prebuilt Windows runtime you point at your own game files, with online play through a relay. SSBU Recomp has no release yet, and ssbu-decomp has no build to play.", "cover": "assets/covers/smash-ultimate-windowsmash.webp", "coverFrom": "wikipedia:Super Smash Bros. Ultimate", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.1.0-alpha.1", "visitsWeek": 0},
  {"id": "superman-64", "title": "Superman 64", "project": "Superman64Recomp", "console": "n64", "year": 1999, "developer": "Titus", "genre": "Action", "stage": "abandoned", "quality": "D", "toolchain": "N64Recomp", "team": "gcsmith", "repo": "https://github.com/gcsmith/Superman64Recomp", "website": null, "version": null, "versionDate": null, "started": "2025-12-19", "updated": "2026-05-27", "stars": 22, "features": [], "ai": false, "summary": "Recompilation of the infamous N64 Superman: playable but unpolished, with a locked frame rate. One of the earliest community demos. Its GitHub repository was deleted or made private in October 2026, so its code and downloads are no longer available.", "requires": "A Superman 64 ROM (N64).", "cover": "assets/covers/superman-64.webp", "coverFrom": "wikipedia:Superman 64", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 0, "visitsWeek": 0},
  {"id": "tales-of-legendia", "title": "Tales of Legendia", "project": "tales-of-legendia-ps2recomp", "console": "ps2", "year": 2005, "developer": "Namco Tales Studio", "genre": "RPG", "stage": "development", "quality": "D", "toolchain": "PS2Recomp", "team": "vamidi", "repo": "https://github.com/vamidi/tales-of-legendia-ps2recomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-09", "updated": "2026-10-18", "stars": 0, "features": [], "ai": false, "summary": "An early static recompilation of the PS2 RPG with PS2Recomp: the game compiles, but some of the PS2's multimedia instructions and system calls are still missing, and the screen stays pink so far. No release yet.", "requires": "Your own Tales of Legendia disc image (PS2). No build to download yet.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/tales-of-legendia.webp", "coverFrom": "libretro:Tales of Legendia (USA)", "platforms": null, "platformsFrom": "manual", "platformsTag": null},
  {"id": "tekken-3", "title": "Tekken 3", "project": "Tekken3Recomp", "console": "ps1", "year": 1998, "developer": "Namco", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "PSXRecomp", "team": "fabioap-cpu", "repo": "https://github.com/fabioap-cpu/Tekken3Recomp", "website": null, "version": "v2.1", "versionDate": "2026-08-27", "started": "2026-07-31", "updated": "2026-08-27", "stars": 142, "features": [], "ai": false, "summary": "Tekken 3 (US version) recompiled with psxrecomp, for Windows. Version 2.1 fixes crashes, and its author reports finishing several stages with it; a netplay option was added but hasn't been tested yet.", "requires": "A Tekken 3 disc image (PS1) and the SCPH1001.BIN BIOS.", "cover": "assets/covers/tekken-3.webp", "coverFrom": "libretro:Tekken 3 (USA)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v2.1", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 4, "visitsWeek": 3},
  {"id": "tekken-5-dark-resurrection", "title": "Tekken 5: Dark Resurrection", "project": "T5DROnline", "console": "ps3", "year": 2007, "developer": "Namco", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "ps3recomp", "team": "TheWishin", "repo": "https://github.com/TheWishin/T5DROnline", "website": null, "version": "v1.0.0", "versionDate": "2026-10-18", "started": "2026-10-17", "updated": "2026-10-18", "stars": 3, "features": ["multiplayer", "online", "launcher", "keyboard"], "ai": true, "summary": "A static recompilation of the PS3 download, Dark Resurrection Online, built on sp00nz's ps3recomp: the launcher checks your own package and license and compiles the game on your PC, no RPCS3 involved. Offline play is complete: Arcade, Ghost, two-player Versus, Survival and Practice at 60 fps, with every fighter and stage, higher render resolutions, borderless fullscreen and keyboard, pads, arcade sticks and hitboxes. Online play between friends works through a public lobby with rollback netcode. Tested on one PC so far. Developed with help from Claude.", "requires": "Your own copy of the US PlayStation Network release, NPUB30009 version 01.00: its .pkg and the .rap license from your account (other versions are refused). Windows 10 or 11 64-bit, a Direct3D 12 graphics card and a processor with SSE4.1; the download brings its own compiler.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/tekken-5-dark-resurrection.webp", "coverFrom": "wikipedia:Tekken 5: Dark Resurrection", "platforms": ["windows"], "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "tekken-6", "title": "Tekken 6", "project": "tekken6-recomp", "console": "x360", "year": 2009, "developer": "Namco Bandai Games", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "ReXGlue", "team": "mahmoud-mess", "repo": "https://github.com/mahmoud-mess/tekken6-recomp", "website": null, "version": "v0.9.4", "versionDate": "2026-10-16", "started": "2026-09-28", "updated": "2026-10-16", "stars": 17, "features": ["launcher"], "ai": false, "summary": "A static recompilation of the Xbox 360 game on the ReXGlue SDK, and the base that other Tekken 6 ports build on. A portable builder turns your own ISO into the game with no tools to install, with a Direct3D 12 renderer recommended and two experimental Vulkan ones. Version 0.9.4 holds 60 fps even on integrated graphics, with internal resolution from 640x360 up to the original 1024x576, an F3 frame-time overlay and crash reports.", "requires": "Your own disc image of the European Xbox 360 release (Tekken 6 (Europe) (En,Ja,Fr,De,Es,It,Ko,Ru)), Windows, a processor with FMA3, and about 20 GB free for the first build.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/tekken-6.webp", "coverFrom": "wikipedia:Tekken 6", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "Iterate", "visitsWeek": 0},
  {"id": "test-drive-unlimited", "title": "Test Drive Unlimited", "project": "TDURecomp", "console": "x360", "year": 2006, "developer": "Eden Games", "genre": "Racing", "stage": "development", "quality": "D", "toolchain": "XenonRecomp", "team": "testdriveupgrade", "repo": "https://github.com/testdriveupgrade/TDURecomp", "website": null, "version": null, "versionDate": null, "started": "2025-06-27", "updated": "2026-04-30", "stars": 8, "features": [], "ai": false, "summary": "Recompilation of Test Drive Unlimited (Xbox 360) with XenonRecomp, at a very early stage of development.", "requires": "Your own copy of Test Drive Unlimited (Xbox 360).", "cover": "assets/covers/test-drive-unlimited.webp", "coverFrom": "wikipedia:Test Drive Unlimited", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "the-darkness", "title": "The Darkness", "project": "DarkRecomp", "console": "x360", "year": 2007, "developer": "Starbreeze Studios", "genre": "Shooter", "stage": "beta", "quality": "B", "toolchain": "XenonRecomp", "team": "portingpete", "repo": "https://github.com/portingpete/The-Darkness-Recomp", "website": null, "version": "v0.1.7", "versionDate": "2026-10-14", "started": "2026-09-15", "updated": "2026-10-16", "stars": 307, "features": ["keyboard-mouse"], "ai": true, "summary": "Native Windows x64 port: the Xbox 360 executable is translated to C++ ahead of time and built into DarkRecomp.exe, with its own D3D11 renderer and no emulation at run time. Playable today from start to finish, with mouse look, controller support, video settings (resolution, FOV, gamma, bloom, frame cap, and VSync), XMA audio, and saves.", "requires": "Your own The Darkness dump (Xbox 360): the original default.xex plus the Content and System folders. The repository ships no game code, assets, or binaries.", "cover": "assets/covers/the-darkness.webp", "coverFrom": "wikipedia:The Darkness (video game)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.1.7", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 46, "visitsWeek": 2},
  {"id": "botw-decomp", "title": "The Legend of Zelda: Breath of the Wild", "project": "botw", "console": "switch", "year": 2017, "developer": "Nintendo EPD", "genre": "Open World", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "zeldaret", "repo": "https://github.com/zeldaret/botw", "website": "https://botw.link/progress", "version": null, "versionDate": null, "started": "2020-08-19", "updated": "2026-10-18", "stars": 2267, "features": [], "ai": false, "summary": "An experimental matching decompilation of the Switch version 1.5.0 by the Zelda Reverse Engineering team: 17.5% of the code and 30.4% of its functions matched as of October 17, 2026. It rebuilds the game's source code rather than porting it, so there is nothing to play yet.", "requires": "No build to play. Contributors work from version 1.5.0, dumped from their own copy.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/botw-decomp.webp", "coverFrom": "wikipedia:The Legend of Zelda: Breath of the Wild", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "botw-savage-wind-recomp", "title": "The Legend of Zelda: Breath of the Wild", "project": "Savage Wind Recomp", "console": "switch", "year": 2017, "developer": "Nintendo EPD", "genre": "Open World", "stage": "development", "quality": "D", "toolchain": "Custom", "team": "Revivedx", "repo": "https://github.com/Revivedx/SavageWindRecomp", "website": null, "version": "v0.1.0-alpha.1", "versionDate": "2026-10-17", "started": "2026-10-16", "updated": "2026-10-17", "stars": 0, "features": [], "ai": true, "summary": "A static recompilation of version 1.8.2 for Windows and Linux. Not playable yet: it boots to the main menu and plays the opening, with the HUD and saves working, but nothing past the first shrine has been tested. Alpha 1 is a Windows preview for testers. The author says nearly all of it was written by AI (Claude).", "requires": "Your own dump of Breath of the Wild version 1.8.2 (exefs and romfs), Windows 10 or later or Linux, a processor with AVX2, a Vulkan 1.3 graphics card and about 35 GB free.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/botw-savage-wind-recomp.webp", "coverFrom": "wikipedia:The Legend of Zelda: Breath of the Wild", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.1.0-alpha.1", "pick": true, "pickNote": "The only one you can run: zeldaret's botw rebuilds the game's source code and has no build to play. Savage Wind's first alpha runs on Windows, though not yet past the opening.", "starsWeek": 0, "visitsWeek": 0},
  {"id": "links-awakening-decomp", "title": "The Legend of Zelda: Link's Awakening", "project": "las-decomp", "console": "switch", "year": 2019, "developer": "Grezzo", "genre": "Action-Adventure", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "Owen-Splat", "repo": "https://github.com/Owen-Splat/las-decomp", "website": null, "version": "v0.4", "versionDate": "2024-06-18", "started": "2024-06-18", "updated": "2026-03-21", "stars": 10, "features": [], "ai": false, "summary": "A decompilation of the 2019 Switch remake kept as a Ghidra project, by the author of the LAS Randomizer that LAS Recomp builds on. It's a reference for modders and researchers, not something to play.", "requires": "Your own main file from the game, Ghidra 10.4 and SwitchLoader 1.6.0.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/links-awakening-decomp.webp", "coverFrom": "wikipedia:The Legend of Zelda: Link's Awakening (2019 video game)", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "links-awakening-las-recomp", "title": "The Legend of Zelda: Link's Awakening", "project": "LAS Recomp", "console": "switch", "year": 2019, "developer": "Grezzo", "genre": "Action-Adventure", "stage": "beta", "quality": "B", "toolchain": "Custom", "team": "peiikai", "repo": "https://github.com/peiikai/LASRecomp", "website": null, "version": "test-depth-3", "versionDate": "2026-10-18", "started": "2026-10-08", "updated": "2026-10-18", "stars": 1276, "features": ["widescreen", "keyboard", "mods"], "ai": true, "summary": "A static recompilation of the Switch remake into native apps for Windows, Linux and Apple silicon Macs, drawn with Vulkan, or Metal and MetalFX on a Mac. An unlocked aspect ratio shows more of the island up to ultrawide, resolution scales up or down, every key and button can be remapped, and an overlay menu sits on F1. Built around Owen_Splat's LAS Randomizer: play vanilla or any randomizer seed and switch between them without restarting. A beta with known crashes and graphics issues at ultrawide. The author says nearly all of it was written by AI (Claude).", "requires": "Your own dump of Link's Awakening version 1.0.0 with no updates (the exefs and romfs folders). Windows and Linux need an x86-64 PC with Vulkan; a Mac needs Apple silicon.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/links-awakening-las-recomp.webp", "coverFrom": "wikipedia:The Legend of Zelda: Link's Awakening (2019 video game)", "platforms": ["windows", "linux", "macos"], "platformsFrom": "release", "platformsTag": "test-perf-4", "visitsWeek": 2},
  {"id": "zelda-majoras-mask", "title": "The Legend of Zelda: Majora's Mask", "project": "Zelda 64: Recompiled", "console": "n64", "year": 2000, "developer": "Nintendo", "genre": "Action-Adventure", "stage": "released", "quality": "S", "toolchain": "N64Recomp", "team": "Zelda64Recomp / Mr. Wiseguy", "repo": "https://github.com/Zelda64Recomp/Zelda64Recomp", "website": "https://zelda64.dev/", "version": "v1.2.2", "versionDate": "2025-08-27", "started": "2023-10-23", "updated": "2026-09-25", "stars": 7461, "features": ["widescreen", "high-fps", "mods", "mod-manager", "steam-deck", "keyboard"], "ai": false, "summary": "The recomp that put the scene on the map in May 2024, built with N64Recomp and the RT64 renderer. Any frame rate and any aspect ratio, including ultrawide, with the original N64 effects intact; community mods installed from an in-game menu, with many on its Thunderstore page; dual analog camera, gyro aim, autosaving and instant load times. Runs on Windows, Linux, Steam Deck and Mac, and the team has a firm no-AI policy.", "requires": "A Majora's Mask ROM (N64, US version, .z64).", "cover": "assets/covers/zelda-majoras-mask.webp", "coverFrom": "libretro:Legend of Zelda, The - Majora's Mask (USA)", "platforms": ["windows", "linux", "macos"], "platformsFrom": "release", "platformsTag": "v1.2.2", "inputFrom": "manual", "modManagerFrom": "manual", "starsWeek": 18, "visitsWeek": 21, "userScore": 10.0, "userScoreCount": 1},
  {"id": "ship-of-harkinian", "title": "The Legend of Zelda: Ocarina of Time", "project": "Ship of Harkinian", "console": "n64", "year": 1998, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "released", "quality": "S", "toolchain": "Decompilation", "team": "HarbourMasters", "repo": "https://github.com/HarbourMasters/Shipwright", "website": "https://www.shipofharkinian.com", "version": "9.3.0", "versionDate": "2026-10-06", "started": "2022-03-22", "updated": "2026-10-18", "stars": 5665, "features": ["widescreen", "high-fps", "mods", "keyboard-mouse", "mod-manager"], "ai": false, "summary": "The Harbour Masters' native PC port of Ocarina of Time, built on the community decompilation and their libultraship library. It plays the whole game, Master Quest included, with widescreen, high frame rates, DirectX 11, OpenGL or Metal rendering, a long list of optional enhancements, a built-in randomizer and custom asset mods, on Windows, Linux and Mac. The Ocarina of Time port most players use.", "requires": "Your own Ocarina of Time ROM in a supported version; you can check yours at ship.equipment.", "cover": "assets/covers/ship-of-harkinian.webp", "coverFrom": "libretro:Legend of Zelda, The - Ocarina of Time (USA)", "platforms": ["windows", "linux", "macos"], "platformsFrom": "release", "platformsTag": "9.3.0", "inputFrom": "github", "modManagerFrom": "github", "starsWeek": 31, "visitsWeek": 12, "userScore": 10.0, "userScoreCount": 1},
  {"id": "zelda-ocarina-of-time", "title": "The Legend of Zelda: Ocarina of Time", "project": "Zelda 64: Recompiled", "console": "n64", "year": 1998, "developer": "Nintendo", "genre": "Action-Adventure", "stage": "development", "quality": "D", "toolchain": "N64Recomp", "team": "Zelda64Recomp", "repo": "https://github.com/Zelda64Recomp/Zelda64Recomp", "website": null, "version": "v1.2.2", "versionDate": "2025-08-27", "started": "2023-10-23", "updated": "2026-09-25", "stars": 7461, "features": [], "ai": false, "summary": "Ocarina of Time is the next game planned for Zelda 64: Recompiled, the project behind the Majora's Mask port. The project still lists it as coming soon, and there's no Ocarina of Time build yet.", "requires": null, "cover": "assets/covers/zelda-ocarina-of-time.webp", "coverFrom": "libretro:Legend of Zelda, The - Ocarina of Time (USA)", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "inputFrom": "manual", "modManagerFrom": "manual", "visitsWeek": 2, "starsWeek": 12},
  {"id": "ocarina-of-time-3d", "title": "The Legend of Zelda: Ocarina of Time 3D", "project": "TriAevum", "console": "3ds", "year": 2011, "developer": "Grezzo", "genre": "Action-Adventure", "stage": "beta", "quality": "B", "toolchain": "Custom", "team": "coccofresco", "repo": "https://github.com/coccofresco/TriAevum", "website": null, "version": "v0.8.0-beta.1.1", "versionDate": "2026-10-18", "started": "2026-09-07", "updated": "2026-10-18", "stars": 506, "features": ["keyboard-mouse"], "ai": true, "summary": "TriAevum: an ahead-of-time static recompilation of the 3DS remake, with its own NRI/Vulkan renderer, a single-screen interface, save states and graphics options. It doesn't recompile the N64 original but Grezzo's version. It leans on code from mature projects (Azahar, Ship of Harkinian, NRI), and its author states that the TriAevum-specific work is entirely AI-assisted, under human direction. Now in beta (0.8), though its README says gameplay testing so far covers the early parts of the game.", "requires": "Your own Ocarina of Time 3D ROM (European or US version), decrypted and in .3ds or .cci format. Windows x64 and a Vulkan-capable GPU.", "cover": "assets/covers/ocarina-of-time-3d.webp", "coverFrom": "libretro:Legend of Zelda, The - Ocarina of Time 3D (USA) (En,Fr,Es)", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v0.8.0-beta.1.1", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 18, "visitsWeek": 3},
  {"id": "zelda-phantom-hourglass", "title": "The Legend of Zelda: Phantom Hourglass", "project": "Phantom Hourglass Recomp", "console": "nds", "year": 2007, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "beta", "quality": "B", "toolchain": "ntr-recomp", "team": "dguillot-gh", "repo": "https://github.com/dguillot-gh/phantom-hourglass-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-12", "updated": "2026-10-17", "stars": 2, "features": ["widescreen", "keyboard-mouse"], "ai": false, "summary": "A static recompilation of the game's ARM9 code, all 24,621 functions, with the rest of the DS (ARM7, graphics, sound) supplied by the melonDS core. Built on the engine of FFCCEOT-Recomp, for Windows and Android phones. Software, OpenGL and Compute renderers with up to 8x upscaling on PC, 16:9 and 21:9 widescreen, mouse as the stylus, keyboard and controllers, an analog-stick mode, buttons for the microphone puzzles, and 12 save-state slots. Plays on PC and a Pixel 8, but there's no download: its scripts install the tools and build it from your ROM.", "requires": "Your own Phantom Hourglass (USA) ROM, clean or with the D-pad patch, and Windows 10 or 11 with about 10 GB free for the build. For the phone app: an Android 8+ 64-bit ARM phone and a USB cable.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/zelda-phantom-hourglass.webp", "coverFrom": "libretro:Legend of Zelda, The - Phantom Hourglass (USA) (DPAD)", "platforms": ["windows", "android"], "platformsFrom": "readme", "platformsTag": null, "visitsWeek": 1, "starsWeek": 1},
  {"id": "skyward-sword-decomp", "title": "The Legend of Zelda: Skyward Sword", "project": "ss", "console": "wii", "year": 2011, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "zeldaret", "repo": "https://github.com/zeldaret/ss", "website": "https://decomp.dev/zeldaret/ss", "version": null, "versionDate": null, "started": "2024-06-14", "updated": "2026-10-17", "stars": 209, "features": [], "ai": false, "summary": "A matching decompilation of the Wii game's USA 1.0 release by the Zelda Reverse Engineering team: 27.9% of the code and 44.1% of its functions matched as of October 18, 2026 (45.3% of the main executable, 16.7% of the modules). It rebuilds the game's source code rather than porting it, so there's nothing to play yet.", "requires": "No build to play. Contributors need the USA 1.0 disc (SOUE01), extracted from their own copy.", "inputFrom": "manual", "modManagerFrom": "manual", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "cover": "assets/covers/skyward-sword-decomp.webp", "coverFrom": "libretro:The Legend of Zelda_ Skyward Sword (USA)", "visitsWeek": 0},
  {"id": "wind-waker", "title": "The Legend of Zelda: The Wind Waker", "project": "ww", "console": "gamecube", "year": 2002, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "development", "quality": "D", "toolchain": "Custom", "team": "sp00nznet", "repo": "https://github.com/sp00nznet/ww", "website": null, "version": null, "versionDate": null, "started": "2026-02-28", "updated": "2026-10-14", "stars": 16, "features": ["keyboard-mouse"], "ai": false, "summary": "Recompilation of the GameCube Wind Waker: it translates the DOL to native C with a runtime that maps GX to Direct3D 11. It renders real geometry at 60 fps, but is still stuck on the title screen (JKRArchive mounting).", "requires": "Your own copy of The Wind Waker (GameCube, US version GZLE01).", "cover": "assets/covers/wind-waker.webp", "coverFrom": "libretro:Legend of Zelda, The - The Wind Waker (USA)", "platforms": ["windows"], "platformsFrom": "readme", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "wind-waker-bluewake", "title": "The Legend of Zelda: The Wind Waker", "project": "BlueWake", "console": "gamecube", "year": 2002, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "beta", "quality": "B", "toolchain": "DolRecomp", "team": "chrissotraidis", "repo": "https://github.com/chrissotraidis/bluewake", "website": null, "version": "v0.8.0", "versionDate": "2026-10-18", "started": "2026-09-28", "updated": "2026-10-18", "stars": 403, "features": ["widescreen", "mods", "keyboard-mouse"], "ai": true, "summary": "A static recompilation with a ready-made Windows download and source builds for Mac, Linux, iPhone, iPad and Apple TV. Adds touch and controller support, widescreen up to 21:9, HD texture packs and Better Wind Waker mods. The game logic still runs at 30 updates a second.", "requires": "Your own Wind Waker disc image (GameCube, USA, GZLE01 revision 0).", "cover": "assets/covers/wind-waker-bluewake.webp", "coverFrom": "libretro:Legend of Zelda, The - The Wind Waker (USA)", "platforms": ["windows", "linux", "macos", "android"], "platformsFrom": "manual", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 25, "visitsWeek": 5},
  {"id": "wind-waker-deep-sea", "title": "The Legend of Zelda: The Wind Waker", "project": "Deep Sea", "console": "gamecube", "year": 2002, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "beta", "quality": "B", "toolchain": "DolRecomp", "team": "AH64-dll", "repo": "https://github.com/AH64-dll/DeepSea", "website": "https://ah64-dll.github.io/DeepSea/", "version": "v1.0.0-beta.4", "versionDate": "2026-09-26", "started": "2026-09-25", "updated": "2026-09-26", "stars": 7, "features": ["widescreen", "high-fps", "keyboard"], "ai": false, "summary": "A native Windows build on a fork of ModernGekko: real 60 fps, true 16:9 widescreen, controller support and a cutscene skip. The launcher builds the game module from your disc on first run, which takes about 10 minutes.", "requires": "Your own Wind Waker disc (GameCube, USA, GZLE01), Windows 10 or 11 and a Vulkan 1.1 GPU.", "cover": "assets/covers/wind-waker-deep-sea.webp", "coverFrom": "libretro:Legend of Zelda, The - The Wind Waker (USA)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v1.0.0-beta.4", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "wind-waker-hd", "title": "The Legend of Zelda: The Wind Waker HD", "project": "ZeldaWWHDRecomp", "console": "wiiu", "year": 2013, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "beta", "quality": "B", "toolchain": "Custom", "team": "ZeldaWWHDRecomp", "repo": "https://github.com/ZeldaWWHDRecomp/ZeldaWWHDRecomp", "website": null, "version": "v0.3.0", "versionDate": "2026-10-15", "started": "2026-10-01", "updated": "2026-10-18", "stars": 753, "features": ["mod-manager"], "ai": false, "summary": "Static recompilation of the Wii U version, separate from the GameCube Wind Waker recomp already in the catalog. It runs natively on Apple Silicon macOS, Linux, Windows, and ARM64 Android: the PowerPC code is translated to C ahead of time, the Cafe OS libraries the game uses are reimplemented natively, and GX2 graphics go straight to Metal on macOS or Vulkan elsewhere. No Cemu runtime and no GPU command emulation. On the Switch it runs as SwitchWakerHD, a community homebrew port built on this one.", "requires": "Your own copy of The Wind Waker HD (Wii U, US edition).", "cover": "assets/covers/wind-waker-hd.webp", "coverFrom": "libretro:Legend of Zelda, The - The Wind Waker HD (USA, Asia) (En,Fr,Es)", "platforms": ["windows", "linux", "macos", "android", "switch"], "platformsFrom": "manual", "platformsTag": null, "inputFrom": "manual", "modManagerFrom": "github", "starsWeek": 104, "visitsWeek": 14},
  {"id": "twilight-princess", "title": "The Legend of Zelda: Twilight Princess", "project": "Dusklight", "console": "gamecube", "year": 2006, "developer": "Nintendo EAD", "genre": "Action-Adventure", "stage": "released", "quality": "S", "toolchain": "Decompilation", "team": "The Twilit Realm", "repo": "https://github.com/TwilitRealm/dusklight", "website": "https://twilitrealm.dev", "version": "v2.0.3", "versionDate": "2026-09-30", "started": "2025-11-30", "updated": "2026-10-11", "stars": 5926, "features": ["high-fps", "mods", "mod-manager"], "ai": false, "summary": "A reverse-engineered reimplementation of Twilight Princess, built on the TP decompilation rather than a static recompiler, with the Aurora layer handling graphics on Windows, Linux, macOS, iOS and Android. It adds higher resolutions and frame rates, authentic or modernized gameplay options, and a full modding system.", "requires": "A dump of your own Twilight Princess disc. Every commercial GameCube and Wii disc works except the Korean Wii release. Wii discs play with the GameCube HUD.", "cover": "assets/covers/twilight-princess.webp", "coverFrom": "libretro:Legend of Zelda, The - Twilight Princess (USA)", "platforms": ["windows", "linux", "macos", "android"], "platformsFrom": "release", "platformsTag": "v2.0.3", "inputFrom": "none", "modManagerFrom": "github", "starsWeek": 54, "visitsWeek": 17},
  {"id": "lotr-return-of-the-king", "title": "The Lord of the Rings: The Return of the King", "project": "rotk-native", "console": "gamecube", "year": 2003, "developer": "EA Redwood Shores", "genre": "Action", "stage": "beta", "quality": "B", "toolchain": "DolRecomp", "team": "kenny08gt", "repo": "https://github.com/kenny08gt/rotk-native", "website": null, "version": null, "versionDate": null, "started": "2026-10-15", "updated": "2026-10-16", "stars": 0, "features": ["keyboard"], "ai": false, "summary": "A native Apple silicon Mac port: DolRecomp for the code and Aurora drawing through Metal. Menus, movies and the first levels run at or near 60 fps. Build from source.", "requires": "Your own Return of the King disc image (GameCube, USA, GKLE69) and an Apple silicon Mac.", "cover": "assets/covers/lotr-return-of-the-king.webp", "coverFrom": "libretro:Lord of the Rings, The - The Return of the King (USA)", "platforms": ["macos"], "platformsFrom": "readme", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 0, "visitsWeek": 0},
  {"id": "lotr-return-of-the-king-xbox", "title": "The Lord of the Rings: The Return of the King", "project": "Athelas", "console": "xbox", "year": 2003, "developer": "EA Redwood Shores", "genre": "Action", "stage": "released", "quality": "A", "toolchain": "XboxXBE-Recomp", "team": "Shagg88", "repo": "https://github.com/Shagg88/Athelas", "website": null, "version": "1.1.1", "versionDate": "2026-10-17", "started": "2026-10-16", "updated": "2026-10-17", "stars": 60, "features": ["widescreen", "high-fps", "keyboard-mouse", "multiplayer", "launcher"], "ai": true, "summary": "A static recompilation of the original Xbox game's code for Windows with Xbox XBE Recomp, part of the Athelas launcher alongside The Two Towers' Xbox port and ROTK Fix for the PC version. It adds widescreen and ultrawide, 30 to 240 fps with the slowdowns and vanishing enemies at high frame rates fixed, anti-aliasing, field of view and draw distance settings, sharper text and menus (from the PC version's fonts, if you have it), keyboard and mouse, and two-player co-op on one PC.", "requires": "Your own US Xbox release, as an .iso or the extracted files; Windows 10 or 11 64-bit and a Direct3D 12 graphics card.", "inputFrom": "manual", "modManagerFrom": "manual", "platforms": ["windows"], "platformsFrom": "manual", "platformsTag": null, "cover": "assets/covers/lotr-return-of-the-king-xbox.webp", "coverFrom": "libretro:Lord of the Rings, The - The Return of the King (USA)"},
  {"id": "lotr-two-towers", "title": "The Lord of the Rings: The Two Towers", "project": "Athelas", "console": "xbox", "year": 2002, "developer": "Stormfront Studios", "genre": "Action", "stage": "released", "quality": "A", "toolchain": "XboxXBE-Recomp", "team": "Shagg88", "repo": "https://github.com/Shagg88/Athelas", "website": null, "version": "1.1.1", "versionDate": "2026-10-17", "started": "2026-10-16", "updated": "2026-10-17", "stars": 60, "features": ["widescreen", "high-fps", "keyboard-mouse", "launcher"], "ai": true, "summary": "A static recompilation of the original Xbox game's code for Windows with Xbox XBE Recomp, part of the Athelas launcher, which also sets up The Return of the King's Xbox port and a fix pack for its PC version. It plays as on the Xbox by default, with widescreen up to 32:9, render scaling from 50% to 300%, 30 to 240 fps at normal game speed, HDR, anti-aliasing and field of view as settings, plus keyboard and mouse, Xbox, PlayStation and Switch controllers, achievements and an F10 settings menu.", "requires": "Your own US Xbox release, as an .iso or the extracted files; Windows 10 or 11 64-bit and a Direct3D 12 graphics card.", "inputFrom": "manual", "modManagerFrom": "manual", "platforms": ["windows"], "platformsFrom": "manual", "platformsTag": null, "cover": "assets/covers/lotr-two-towers.webp", "coverFrom": "libretro:Lord of the Rings, The - The Two Towers (USA)"},
  {"id": "the-simpsons-game", "title": "The Simpsons Game", "project": "TheSimpsonsGameRecomp", "console": "x360", "year": 2007, "developer": "EA Redwood Shores", "genre": "Platformer", "stage": "development", "quality": "C", "toolchain": "ReXGlue", "team": "YesterMester", "repo": "https://github.com/YesterMester/TheSimpsonsGameRecomp", "website": null, "version": "v0.0.6.5", "versionDate": "2026-10-10", "started": "2026-07-04", "updated": "2026-10-11", "stars": 362, "features": ["keyboard-mouse"], "ai": true, "summary": "Recompilation of The Simpsons Game (2007, Xbox 360) with ReXGlue. Work in progress: the current goal is getting the game running.", "requires": "Your own copy of The Simpsons Game (Xbox 360).", "cover": "assets/covers/the-simpsons-game.webp", "coverFrom": "wikipedia:The Simpsons Game", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v0.0.6.5", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 18, "visitsWeek": 0},
  {"id": "simpsons-wrestling", "title": "The Simpsons Wrestling", "project": "The Simpsons Wrestling Recompiled", "console": "ps1", "year": 2001, "developer": "Big Ape Productions", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "PSXRecomp", "team": "TekRantGaming", "repo": "https://github.com/TekRantGaming/simpsons-wrestling-recompiled", "website": null, "version": "v1.0.0", "versionDate": "2026-10-07", "started": "2026-10-07", "updated": "2026-10-13", "stars": 26, "features": ["widescreen", "high-fps", "multiplayer", "keyboard"], "ai": true, "summary": "Recompiled from the PlayStation version with PSXRecomp. Matches run in true 16:9 with more of the arena on screen, at 60 fps at the original game speed (120 experimental), rendered at up to 8K without the PlayStation's wobbling polygons. Intros can be skipped and every wrestler and circuit unlocked, with two players on controllers or keyboard. Minor known issues: pausing in widescreen puts some labels back at their 4:3 spots. Made almost entirely with Claude Code, the author says.", "requires": "Your own disc image of The Simpsons Wrestling (PlayStation, USA, SLUS-01227) as .cue and .bin, and an OpenGL 3.3 graphics card.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/simpsons-wrestling.webp", "coverFrom": "libretro:Simpsons Wrestling, The (USA)", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v1.0.0", "visitsWeek": 3, "starsWeek": 2},
  {"id": "timesplitters-2", "title": "TimeSplitters 2", "project": "split2-recomp", "console": "xbox", "year": 2002, "developer": "Free Radical Design", "genre": "Shooter", "stage": "development", "quality": "C", "toolchain": "xboxrecomp", "team": "phobos665", "repo": "https://github.com/phobos665/split2-recomp", "website": null, "version": "v0.1", "versionDate": "2026-09-30", "started": "2026-09-22", "updated": "2026-10-15", "stars": 14, "features": ["keyboard"], "ai": false, "summary": "split2-recomp: a static recompilation of the Xbox version of TimeSplitters 2 for Windows, using xboxrecomp. There are no prebuilt executables: the game’s code is translated to C on your own PC from your copy, then compiled. The front end and a story mode level have been played, at 60 fps, with higher internal resolution, a frame counter, and rebindable controls; the other modes haven’t been tested yet.", "requires": "Your own copy of TimeSplitters 2 for Xbox, PAL or US release, extracted from the disc. Building it requires Windows 10 or 11, Visual Studio, CMake, Python, and Git.", "cover": "assets/covers/timesplitters-2.webp", "coverFrom": "libretro:TimeSplitters 2 (USA)", "platforms": ["windows", "macos"], "platformsFrom": "readme", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 5, "visitsWeek": 0},
  {"id": "tomba", "title": "Tomba!", "project": "TombaRecomp", "console": "ps1", "year": 1997, "developer": "Whoopee Camp", "genre": "Platformer", "stage": "beta", "quality": "B", "toolchain": "PSXRecomp", "team": "mstan", "repo": "https://github.com/mstan/TombaRecomp", "website": null, "version": "v0.20.0-alpha", "versionDate": "2026-10-09", "started": "2026-03-15", "updated": "2026-10-10", "stars": 69, "features": ["keyboard"], "ai": false, "summary": "Tomba! driven end to end through psxrecomp. It reaches real gameplay (jumping, grabbing, quests), but with audio timing glitches and softlocks.", "requires": "A Tomba! disc image (PS1) and the SCPH1001.BIN BIOS.", "cover": "assets/covers/tomba.webp", "coverFrom": "libretro:Tomba! (USA)", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v0.20.0-alpha", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 2, "visitsWeek": 0},
  {"id": "tomba-2", "title": "Tomba! 2: The Evil Swine Return", "project": "Tomba2Recomp", "console": "ps1", "year": 1999, "developer": "Whoopee Camp", "genre": "Platformer", "stage": "beta", "quality": "B", "toolchain": "PSXRecomp", "team": "mstan", "repo": "https://github.com/mstan/Tomba2Recomp", "website": null, "version": "v0.2.1", "versionDate": "2026-10-13", "started": "2026-07-03", "updated": "2026-10-13", "stars": 17, "features": [], "ai": false, "summary": "Native recompilation of Tomba! 2 (US version) with psxrecomp, with 21:9 support and full-frame-rate OpenGL. Part of the R.A.I.D. ecosystem.", "requires": "A disc image of Tomba! 2 (PS1, US version).", "cover": "assets/covers/tomba-2.webp", "coverFrom": "libretro:Tomba! 2 - The Evil Swine Return (USA)", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v0.2.1", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 3, "visitsWeek": 0},
  {"id": "tomodachi-life-recomp", "title": "Tomodachi Life: Living the Dream", "project": "tomodachi-ltd-recomp", "console": "switch", "year": 2026, "developer": "Nintendo", "genre": "Simulation", "stage": "development", "quality": "D", "toolchain": "Custom", "team": "RussoPhone", "repo": "https://github.com/RussoPhone/tomodachi-ltd-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-08", "updated": "2026-10-17", "stars": 39, "features": [], "ai": true, "summary": "An experimental static recompilation that leans on emulation code taken from the suyu Switch emulator, so it's part native port and part emulator. An installer builds it in ten steps from your own game file and keys. Linux is the main platform (tested on Arch, EndeavourOS and Fedora); the Windows installer is experimental and hasn't been tried with the full game.", "requires": "Your own .nsp of Tomodachi Life: Living the Dream version 1.0.0 without updates, and the prod.keys from your own Switch.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/tomodachi-life-recomp.webp", "coverFrom": "wikipedia:Tomodachi Life: Living the Dream", "platforms": ["linux"], "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "transformers-armada", "title": "Transformers Armada: Prelude to Energon", "project": "transformers-ps2-decomp", "console": "ps2", "year": 2004, "developer": "Melbourne House", "genre": "Action", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "kayliox", "repo": "https://github.com/kayliox/transformers-ps2-decomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-15", "updated": "2026-10-18", "stars": 5, "features": [], "ai": true, "summary": "A matching decompilation of the PS2 game, released in Europe as Transformers: 14.7% of its 22,295 functions matched as of October 17, 2026, working from the European version. The source isn't public yet. Once it's done, the plan is a native PC version with HD, ultrawide, 60 fps and mods. The author says AI writes first drafts, and every function is checked byte for byte against the original before it goes in.", "requires": "No build yet. The European version (SLES-52388) is the one being decompiled.", "inputFrom": "manual", "modManagerFrom": "manual", "coverFrom": "libretro:Transformers (USA)", "cover": "assets/covers/transformers-armada.webp", "visitsWeek": 0, "starsWeek": 1},
  {"id": "tsumu-light", "title": "Tsumu Light", "project": "TsumuLightRecomp", "console": "ps1", "year": null, "developer": "Sony Music Entertainment", "genre": "Puzzle", "stage": "development", "quality": "C", "toolchain": "PSXRecomp", "team": "mstan", "repo": "https://github.com/mstan/TsumuLightRecomp", "website": null, "version": "v0.1.0", "versionDate": "2026-10-08", "started": "2026-07-07", "updated": "2026-10-08", "stars": 7, "features": ["keyboard"], "ai": false, "summary": "Native recompilation of Tsumu Light (Japanese version) with psxrecomp, with an English translation patch. An obscure Japanese title.", "requires": "A disc image of Tsumu Light (PS1, Japanese version).", "cover": "assets/covers/tsumu-light.webp", "coverFrom": "libretro:Tsumu Light (Japan)", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v0.1.0", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "valkyrie-profile", "title": "Valkyrie Profile", "project": "ValkyrieRecomp", "console": "ps1", "year": 1999, "developer": "tri-Ace", "genre": "RPG", "stage": "released", "quality": "B", "toolchain": "PSXRecomp", "team": "Ed1z19", "repo": "https://github.com/Ed1z19/ValkyrieRecomp", "website": null, "version": "v1.0.1", "versionDate": "2026-09-04", "started": "2026-08-30", "updated": "2026-09-06", "stars": 112, "features": [], "ai": false, "summary": "Static recompilation of tri-Ace’s RPG, built on psxrecomp and recomp-ui. It supports both discs (SLUS-01156 and SLUS-01179), selected from the launcher, optional 16:9 widescreen over the original 4:3, OpenGL or software rendering, and controller and memory card support. Its author calls it a work in progress, in compatibility testing.", "requires": "Your own disc images for both Valkyrie Profile discs (US NTSC-U edition). It uses OpenBIOS through psxrecomp, so you don’t need a console BIOS.", "cover": "assets/covers/valkyrie-profile.webp", "coverFrom": "libretro:Valkyrie Profile (USA)", "platforms": ["windows", "linux", "macos"], "platformsFrom": "release", "platformsTag": "v1.0.1", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "virtual-pro-wrestling-2", "title": "Virtual Pro Wrestling 2", "project": "VPW2Recomp", "console": "n64", "year": 2000, "developer": "AKI Corporation", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "N64Recomp", "team": "jessetbh", "repo": "https://github.com/jessetbh/VPW2Recomp", "website": null, "version": "v0.2.0", "versionDate": "2026-10-14", "started": "2026-07-17", "updated": "2026-10-17", "stars": 7, "features": ["widescreen", "high-fps", "ray-tracing", "multiplayer", "keyboard", "mods"], "ai": false, "summary": "A static recompilation of the Japanese N64 game, the last of jessetbh's AKI wrestling ports. Full matches with music, saves and two controllers play at high resolution through RT64, with widescreen, 60 or 120 fps by interpolation, ray-traced arena lighting, a CRT filter and HDR (the last four experimental). English fan translations and ROM hacks run as patch mods from its Mods menu. Windows only for now.", "requires": "Your own Virtual Pro Wrestling 2 ROM (N64, Japan), a Direct3D 12 or Vulkan 1.2 graphics card and a processor with SSE4.1.", "inputFrom": "manual", "modManagerFrom": "manual", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.2.0", "coverFrom": "libretro:Virtual Pro Wrestling 2 - Oudou Keishou (Japan)", "cover": "assets/covers/virtual-pro-wrestling-2.webp", "visitsWeek": 0},
  {"id": "virtual-pro-wrestling-64", "title": "Virtual Pro Wrestling 64", "project": "VPW64Recomp", "console": "n64", "year": 1997, "developer": "AKI Corporation", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "N64Recomp", "team": "jessetbh", "repo": "https://github.com/jessetbh/VPW64Recomp", "website": null, "version": "v0.2.0", "versionDate": "2026-10-14", "started": "2026-07-13", "updated": "2026-10-17", "stars": 9, "features": ["widescreen", "high-fps", "ray-tracing", "keyboard", "mods"], "ai": false, "summary": "A static recompilation of the Japanese N64 game, VPW2's predecessor, in jessetbh's family of AKI wrestling ports. Menus and matches play at high resolution through RT64 with music, rumble and Controller Pak saves that keep themselves, plus widescreen, 60 or 120 fps by interpolation, ray-traced arena lighting, a CRT filter and HDR (the last four experimental). English fan translations and ROM hacks run as patch mods. Quitting in the middle of a match can crash on the way out, without harming your save. Windows only for now.", "requires": "Your own Virtual Pro Wrestling 64 ROM (N64, Japan), a Direct3D 12 or Vulkan 1.2 graphics card and a processor with SSE4.1.", "inputFrom": "manual", "modManagerFrom": "manual", "coverFrom": "libretro:Virtual Pro Wrestling 64 (Japan)", "cover": "assets/covers/virtual-pro-wrestling-64.webp", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.2.0", "visitsWeek": 0},
  {"id": "viva-pinata", "title": "Viva Piñata", "project": "VivaPinataRecomp", "console": "x360", "year": 2006, "developer": "Rare", "genre": "Simulation", "stage": "development", "quality": "D", "toolchain": "XenonRecomp", "team": "VivaPinataRecomp", "repo": "https://github.com/VivaPinataRecomp/VivaPinataRecomp", "website": null, "version": null, "versionDate": null, "started": "2025-04-20", "updated": "2025-04-21", "stars": 5, "features": [], "ai": false, "summary": "Recompilation project for the original Viva Piñata. Set up in April 2025 with no public builds since. The sequel has its own, more active recomp.", "requires": "Your own copy of Viva Piñata (Xbox 360).", "cover": "assets/covers/viva-pinata.webp", "coverFrom": "wikipedia:Viva Piñata (video game)", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 0, "visitsWeek": 0},
  {"id": "viva-pinata-tip", "title": "Viva Piñata: Trouble in Paradise", "project": "ReTiP", "console": "x360", "year": 2008, "developer": "Rare", "genre": "Simulation", "stage": "released", "quality": "A", "toolchain": "ReXGlue", "team": "SolarCookies", "repo": "https://github.com/SolarCookies/TiP-Recomp", "website": "https://gamejolt.com/games/retip/1087631", "version": "1.13.0", "versionDate": "2026-10-01", "started": "2026-03-14", "updated": "2026-10-03", "stars": 216, "features": ["widescreen", "high-fps", "mods", "mod-manager", "steam-deck", "keyboard-mouse"], "ai": false, "summary": "ReTiP recompiles the game on ReXGlue with its own native renderer (DirectX 12 on Windows, Vulkan on Linux and Steam Deck) that fixes Xenia's rendering issues and runs well ahead of emulation. Fully playable with very minimal issues. Adds an unlocked frame rate, custom aspect ratios, graphics presets, and a built-in mod manager with a Thunderstore browser (F5) for texture, audio, data and Lua mods. macOS support is on the way, and a GameJolt build adds trophies for the game's achievements. The project has a strict no-AI policy.", "requires": "Your own Viva Piñata: Trouble in Paradise disc image (Xbox 360). A controller, or a mouse with forward and back buttons.", "cover": "assets/covers/viva-pinata-tip.webp", "coverFrom": "wikipedia:Viva Piñata: Trouble in Paradise", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "1.13.0", "inputFrom": "manual", "modManagerFrom": "manual", "starsWeek": 7, "visitsWeek": 6},
  {"id": "wave-race-64", "title": "Wave Race 64", "project": "WaveRace64Recompiled", "console": "n64", "year": 1996, "developer": "Nintendo EAD", "genre": "Racing", "stage": "development", "quality": "D", "toolchain": "N64Recomp", "team": "chronic8000", "repo": "https://github.com/chronic8000/WaveRace64Recompiled", "website": null, "version": null, "versionDate": null, "started": "2026-06-21", "updated": "2026-06-21", "stars": 7, "features": [], "ai": false, "summary": "Native Wave Race 64 port via static recompilation. Very early, and not playable yet.", "requires": "A Wave Race 64 ROM (N64, .z64).", "cover": "assets/covers/wave-race-64.webp", "coverFrom": "wikipedia:Wave Race 64", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 0, "visitsWeek": 0},
  {"id": "wave-race-64-gomesvieira", "title": "Wave Race 64", "project": "wave-race-64-recomp", "console": "n64", "year": 1996, "developer": "Nintendo EAD", "genre": "Racing", "stage": "released", "quality": "A", "toolchain": "N64Recomp", "team": "danielgomesvieira2000", "repo": "https://github.com/danielgomesvieira2000/wave-race-64-recomp", "website": null, "version": "v1.0.2", "versionDate": "2026-09-14", "started": "2026-09-04", "updated": "2026-10-15", "stars": 91, "features": [], "ai": true, "summary": "Native port by static recompilation with N64Recomp, running on N64ModernRuntime, with RT64 for rendering and RecompFrontend for menus and controller support. It’s independent of the other two Wave Race 64 recomps in the catalog: unlike the one listed simply as “Wave Race 64,” which stalled at booting to noise, this one has playable beta builds. The elliotttate fork adds an Apple Silicon macOS build, HD textures, and a replacement soundtrack. Both repositories state that the port is AI-coded.", "requires": "Your own Wave Race 64 ROM, which must be the US Rev A (v1.1, 8 MiB .z64). The US v1.0, Japanese, European, and Shindou versions won’t work: their code is laid out differently, and every address in the project is tied to Rev A.", "cover": "assets/covers/wave-race-64-gomesvieira.webp", "coverFrom": "wikipedia:Wave Race 64", "platforms": ["windows", "linux"], "platformsFrom": "release", "platformsTag": "v1.0.2", "inputFrom": "none", "modManagerFrom": "none", "starsWeek": 11, "visitsWeek": 0},
  {"id": "wave-race-64-racewave46", "title": "Wave Race 64", "project": "RaceWave46", "console": "n64", "year": 1996, "developer": "Nintendo EAD", "genre": "Racing", "stage": "released", "quality": "A", "toolchain": "Custom", "team": "DomazinUS", "repo": "https://github.com/DomazinUS/RaceWave46", "website": null, "version": "v1.0.0", "versionDate": "2026-09-16", "started": "2026-09-16", "updated": "2026-09-20", "stars": 123, "features": ["keyboard"], "ai": true, "summary": "The third independent Wave Race 64 project in the catalog, unrelated to the other two. It brings the US Rev 1 version to PC with higher resolutions, interpolated presentation, widescreen, new graphics options, and expanded local multiplayer, while keeping the original’s modes and progression: championship, time trials, stunt mode, two-player, and Dolphin Park. Its author states it’s AI-assisted.", "requires": "Your own Wave Race 64 ROM (N64), US Rev 1 version.", "cover": "assets/covers/wave-race-64-racewave46.webp", "coverFrom": "wikipedia:Wave Race 64", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v1.0.0", "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 4, "visitsWeek": 0},
  {"id": "wave-race-blue-storm", "title": "Wave Race: Blue Storm", "project": "bluestorm-recomp", "console": "gamecube", "year": 2001, "developer": "Nintendo Software Technology", "genre": "Racing", "stage": "development", "quality": "D", "toolchain": "gcn-recomp", "team": "ethannicholas", "repo": "https://github.com/ethannicholas/bluestorm-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-09-29", "updated": "2026-10-16", "stars": 3, "features": ["keyboard"], "ai": false, "summary": "Static recompilation for macOS, Windows and the Meta Quest 3 in VR, built on the shared gcn-recomp toolkit. Source only.", "requires": "Your own Wave Race: Blue Storm disc image (GameCube, North America).", "cover": "assets/covers/wave-race-blue-storm.webp", "coverFrom": "libretro:Wave Race - Blue Storm (USA)", "platforms": ["windows", "macos"], "platformsFrom": "readme", "platformsTag": null, "inputFrom": "github", "modManagerFrom": "none", "starsWeek": 2, "visitsWeek": 0},
  {"id": "wcw-vs-nwo-world-tour", "title": "WCW vs. nWo World Tour", "project": "WCWvsNWOWorldTourRecomp", "console": "n64", "year": 1997, "developer": "AKI Corporation", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "N64Recomp", "team": "jessetbh", "repo": "https://github.com/jessetbh/WCWvsNWOWorldTourRecomp", "website": null, "version": "v0.2.0", "versionDate": "2026-10-14", "started": "2026-07-06", "updated": "2026-10-17", "stars": 42, "features": ["keyboard"], "ai": false, "summary": "Native PC port of WCW vs. nWo World Tour via static recompilation: full matches, local multiplayer, saves, and rumble.", "requires": "A WCW vs. nWo World Tour ROM (N64, .z64).", "cover": "assets/covers/wcw-vs-nwo-world-tour.webp", "coverFrom": "libretro:WCW vs. nWo - World Tour (USA)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.2.0", "inputFrom": "manual", "modManagerFrom": "none", "starsWeek": 2, "visitsWeek": 0},
  {"id": "wcw-nwo-revenge", "title": "WCW/nWo Revenge", "project": "WCWnWoRevengeRecomp", "console": "n64", "year": 1998, "developer": "AKI Corporation", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "N64Recomp", "team": "jessetbh", "repo": "https://github.com/jessetbh/WCWnWoRevengeRecomp", "website": null, "version": "v0.2.0", "versionDate": "2026-10-14", "started": "2026-07-08", "updated": "2026-10-17", "stars": 26, "features": ["widescreen", "high-fps", "ray-tracing", "keyboard", "mods"], "ai": false, "summary": "A static recompilation of the N64 game, the World Tour port's sequel in jessetbh's family of AKI wrestling ports. Menus and matches play at high resolution through RT64 with music, rumble and cartridge saves that keep themselves, with no pak juggling, plus widescreen, 60 or 120 fps by interpolation, ray-traced arena lighting, a CRT filter and HDR (the last four experimental). ROM hacks run as patch mods. At 60 fps about 1% of frames can flicker in brightness. Windows only for now.", "requires": "Your own WCW/nWo Revenge ROM (N64, USA), a Direct3D 12 or Vulkan 1.2 graphics card and a processor with SSE4.1.", "cover": "assets/covers/wcw-nwo-revenge.webp", "coverFrom": "libretro:WCW-nWo Revenge (USA)", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.2.0", "inputFrom": "manual", "modManagerFrom": "none", "starsWeek": 1, "visitsWeek": 0},
  {"id": "wwe-12", "title": "WWE '12", "project": "wwe12-pc", "console": "x360", "year": 2011, "developer": "Yuke's", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "ReXGlue", "team": "iMrBurn", "repo": "https://github.com/iMrBurn/wwe12-pc", "website": null, "version": "v0.8.0-beta", "versionDate": "2026-10-17", "started": "2026-10-11", "updated": "2026-10-18", "stars": 36, "features": ["high-fps", "launcher", "keyboard", "mods"], "ai": false, "summary": "A native Windows port of the Xbox 360 version, recompiled with ReXGlue and drawn by a Vulkan renderer adapted from nefariousjosiah's SmackDown vs. Raw ports. Menus, matches of up to six wrestlers and entrances run at 60 fps (entrances at 30 like the console, or 60 as an experiment), from 540p to 4K, with loading about twice as fast. Its launcher handles settings, mods, saves (including your Xbox 360 ones) and one-click updates; DLC and all five European languages work. Some Intel and AMD cards still show glitches, and 1.0 is planned once the known bugs are fixed.", "requires": "Your own disc image of WWE '12 for Xbox 360, Windows 10 or 11 and a Vulkan 1.2 graphics card (not the Intel HD 4000 to 6000 series).", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/wwe-12.webp", "coverFrom": "wikipedia:WWE '12", "platforms": ["windows"], "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "wwe-13", "title": "WWE '13", "project": "WWE '13 Recomp", "console": "x360", "year": 2012, "developer": "Yuke's", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "ReXGlue", "team": "PromethenDev", "repo": "https://github.com/PromethenDev/wwe13-recomp", "website": null, "version": "v1.5", "versionDate": "2026-10-13", "started": "2026-10-02", "updated": "2026-10-13", "stars": 86, "features": ["high-fps", "launcher", "keyboard"], "ai": false, "summary": "A static recompilation of the Xbox 360 version for Windows and Linux, built on HollywoodAkeem's ReXGlue fork for Yuke's games. A launcher installs your game files, title update and DLC, updates itself, and has a Content page for custom Superstars, entrances, arenas, logos and your own entrance music. 480p to 1440p, Classic frame rate (60 in matches, 30 in entrances, like the console) or 60 everywhere, five languages, and full keyboard controls. 1080p is hidden for now because of crowd glitches.", "requires": "Your own Xbox 360 copy of WWE '13 (a game folder or disc image) with title update 2.0.1.0, Windows 10 or 11 or Linux, a processor with AVX2 and a Vulkan graphics card.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/wwe-13.webp", "coverFrom": "wikipedia:WWE '13", "platforms": ["windows", "linux"], "platformsFrom": "readme", "platformsTag": null, "visitsWeek": 0},
  {"id": "wwe-2k14", "title": "WWE 2K14", "project": "WWE 2K14 Recomp", "console": "x360", "year": 2013, "developer": "Yuke's", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "ReXGlue", "team": "PromethenDev", "repo": "https://github.com/PromethenDev/wwe2k14-recomp", "website": null, "version": "v1.0.0", "versionDate": "2026-10-15", "started": "2026-10-11", "updated": "2026-10-15", "stars": 55, "features": ["launcher", "keyboard"], "ai": false, "summary": "A static recompilation of the Xbox 360 version for Windows and Linux, from the team behind WWE '13 Recomp and on the same ReXGlue fork. The launcher installs your game files, title update and DLC, updates itself and takes your own music. 720p to 1440p, keyboard controls modelled on the modern WWE 2K games, and typing names on your PC keyboard. The game runs at its own pace: there are no frame rate or anti-aliasing overrides, and frame rates can dip in matches on some PCs.", "requires": "Your own Xbox 360 copy of WWE 2K14 with title update 1.0.3, Windows 10 or 11 or Linux, a processor with AVX2 and a dedicated graphics card with Vulkan (integrated graphics aren't well supported yet).", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/wwe-2k14.webp", "coverFrom": "wikipedia:WWE 2K14", "platforms": ["windows", "linux"], "platformsFrom": "readme", "platformsTag": null, "visitsWeek": 1},
  {"id": "smackdown-vs-raw-2007", "title": "WWE SmackDown vs. Raw 2007", "project": "SVR07-Recomp", "console": "x360", "year": 2006, "developer": "Yuke's", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "ReXGlue", "team": "HollywoodAkeem", "repo": "https://github.com/HollywoodAkeem/SVR07-Recomp", "website": null, "version": "v1.0", "versionDate": "2026-04-24", "started": "2026-03-24", "updated": "2026-05-27", "stars": 153, "features": [], "ai": false, "summary": "A static recompilation of the Xbox 360 game on its author's own ReXGlue fork, the one the later WWE ports build on. Playable end to end at a stable 60 fps with the retail timing: menus, match types, Create-a-Superstar, season mode and saves all work, with output up to 4K. About one session in ten ends in a graphics-device crash, and the internal resolution and aspect ratio are still locked to the console's.", "requires": "Your own Xbox 360 copy of WWE SmackDown vs. Raw 2007 (USA/Canada recommended), Windows 10 or 11 and a Direct3D 12 graphics card.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/smackdown-vs-raw-2007.webp", "coverFrom": "wikipedia:WWE SmackDown vs. Raw 2007", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.5a", "visitsWeek": 2},
  {"id": "smackdown-vs-raw-2011", "title": "WWE SmackDown vs. Raw 2011", "project": "wwe-svr2011-pc", "console": "x360", "year": 2010, "developer": "Yuke's", "genre": "Fighting", "stage": "released", "quality": "A", "toolchain": "ReXGlue", "team": "KaikoClanworth1", "repo": "https://github.com/KaikoClanworth1/wwe-svr2011-pc", "website": null, "version": "v2.1.3", "versionDate": "2026-10-15", "started": "2026-09-28", "updated": "2026-10-16", "stars": 99, "features": ["widescreen", "launcher", "steam-deck", "mods", "mod-manager"], "ai": true, "summary": "A native port of the Xbox 360 game for Windows and Android, recompiled with ReXGlue. 720p to 4K at a steady 60 fps, true ultrawide in matches and entrances, a self-updating launcher, your own entrance music and titantron movies, up to 10 HD logos per superstar, Paint Tool import and export, achievements, five languages, and a Mod Maker for arenas, superstars and move packs. Android plays the full game with touch controls; the Steam Deck runs it through Proton at 55 to 60 fps. Online modes aren't available. The author says Claude Code wrote most of it.", "requires": "Your own disc image of the Xbox 360 version (the PS3, Wii, PS2 and PSP versions won't work), Windows 10 or 11 with a Direct3D 12 graphics card, and about 6 GB free.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/smackdown-vs-raw-2011.webp", "coverFrom": "wikipedia:WWE SmackDown vs. Raw 2011", "platforms": ["windows", "android"], "platformsFrom": "manual", "platformsTag": null, "visitsWeek": 0},
  {"id": "smackdown-vs-raw-2011-shaneomac", "title": "WWE SmackDown vs. Raw 2011", "project": "SVR2011-Recomp", "console": "x360", "year": 2010, "developer": "Yuke's", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "ReXGlue", "team": "shaneomac1337", "repo": "https://github.com/shaneomac1337/SVR2011-Recomp", "website": null, "version": "v0.5.0", "versionDate": "2026-10-02", "started": "2026-09-28", "updated": "2026-10-02", "stars": 17, "features": ["launcher"], "ai": false, "summary": "A separate Windows port of the Xbox 360 game on the ReXGlue SDK, with a launcher that checks and copies your disc's files once. Exhibition matches with entrances and finishers, backstage brawls, Create a Superstar, Superstar Threads and the Paint Tool are tested and play at 60 fps, with FSR 1 and CAS sharpening up to 3x. Road to WrestleMania, Universe and online haven't been tested and may crash.", "requires": "Your own disc image of the USA/Europe Xbox 360 release, Windows 10 or 11, a Vulkan graphics card and about 6 GB free.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/smackdown-vs-raw-2011-shaneomac.webp", "coverFrom": "wikipedia:WWE SmackDown vs. Raw 2011", "platforms": ["windows"], "platformsFrom": "readme", "platformsTag": null, "visitsWeek": 0},
  {"id": "smackdown-here-comes-the-pain", "title": "WWE SmackDown! Here Comes the Pain", "project": "hctp-recomp", "console": "ps2", "year": 2003, "developer": "Yuke's", "genre": "Fighting", "stage": "development", "quality": "D", "toolchain": "PS2Recomp", "team": "BigDaddyJRich", "repo": "https://github.com/BigDaddyJRich/hctp-recomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-13", "updated": "2026-10-14", "stars": 3, "features": [], "ai": false, "summary": "A static recompilation of the PS2 wrestling game with PS2Recomp, built on Def Jam Vendetta Recompiled. It boots through the memory-card screens, plays the intro and menu movies with music, commentary, crowd audio and sound effects, and runs demo matches at 32 to 44 fps; a native renderer for the 3D models is in progress. No release yet: you build it from your own disc.", "requires": "Your own WWE SmackDown! Here Comes the Pain disc image (PS2, NTSC-U, SLUS-20787), and Windows with a Vulkan graphics card. No download yet.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/smackdown-here-comes-the-pain.webp", "coverFrom": "libretro:WWE SmackDown! Here Comes the Pain (USA)", "platforms": ["windows"], "platformsFrom": "readme", "platformsTag": null},
  {"id": "wwf-no-mercy", "title": "WWF No Mercy", "project": "WWFNoMercyRecomp", "console": "n64", "year": 2000, "developer": "AKI Corporation", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "N64Recomp", "team": "jessetbh", "repo": "https://github.com/jessetbh/WWFNoMercyRecomp", "website": null, "version": "v0.2.0", "versionDate": "2026-10-14", "started": "2026-07-15", "updated": "2026-10-17", "stars": 36, "features": ["widescreen", "high-fps", "ray-tracing", "keyboard", "mods"], "ai": false, "summary": "A static recompilation of the N64 game, one of jessetbh's family of AKI wrestling ports. Menus and matches play at high resolution through RT64 with music, rumble and flash saves that keep themselves, plus widescreen, 60 or 120 fps by interpolation, ray-traced arena lighting, a CRT filter and HDR (the last four experimental). Keyboard and controller are fully rebindable, and ROM hacks run as patch mods from its Mods menu. Windows only for now.", "requires": "Your own WWF No Mercy ROM (N64, USA Rev 1; other dumps are refused), a Direct3D 12 or Vulkan 1.2 graphics card and a processor with SSE4.1.", "inputFrom": "manual", "modManagerFrom": "manual", "coverFrom": "libretro:WWF No Mercy (USA) (Rev 1)", "cover": "assets/covers/wwf-no-mercy.webp", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.2.0", "visitsWeek": 0},
  {"id": "wwf-wrestlemania-2000", "title": "WWF WrestleMania 2000", "project": "WWFWrestleMania2000Recomp", "console": "n64", "year": 1999, "developer": "AKI Corporation", "genre": "Fighting", "stage": "beta", "quality": "B", "toolchain": "N64Recomp", "team": "jessetbh", "repo": "https://github.com/jessetbh/WWFWrestleMania2000Recomp", "website": null, "version": "v0.2.0", "versionDate": "2026-10-14", "started": "2026-07-14", "updated": "2026-10-17", "stars": 17, "features": ["widescreen", "high-fps", "ray-tracing", "keyboard", "mods"], "ai": false, "summary": "A static recompilation of the N64 game, from the same family as the No Mercy and World Tour ports. Menus and matches play at high resolution through RT64 with music and rumble, and the cartridge save and Controller Pak both persist on their own, with no pak swapping. Adds widescreen, 60 or 120 fps by interpolation, ray-traced arena lighting, a CRT filter and HDR (the last four experimental), rebindable keyboard and controller, and ROM hacks as patch mods. Windows only for now.", "requires": "Your own WWF WrestleMania 2000 ROM (N64, USA V1.2; earlier revisions are refused), a Direct3D 12 or Vulkan 1.2 graphics card and a processor with SSE4.1.", "inputFrom": "manual", "modManagerFrom": "manual", "coverFrom": "libretro:WWF WrestleMania 2000 (USA)", "cover": "assets/covers/wwf-wrestlemania-2000.webp", "platforms": ["windows"], "platformsFrom": "release", "platformsTag": "v0.2.0", "visitsWeek": 0},
  {"id": "xenoblade-chronicles-2-decomp", "title": "Xenoblade Chronicles 2", "project": "xc2-decomp", "console": "switch", "year": 2017, "developer": "Monolith Soft", "genre": "RPG", "stage": "development", "quality": "D", "toolchain": "Decompilation", "team": "KevinBonnoron", "repo": "https://github.com/KevinBonnoron/xc2-decomp", "website": null, "version": null, "versionDate": null, "started": "2026-10-13", "updated": "2026-10-18", "stars": 0, "features": [], "ai": false, "summary": "A matching decompilation of version 1.0.0, picked because its executable still carries the names of about 51,000 functions; later updates are stripped. 23,061 of 48,739 functions (22.4% of the code) matched as of October 17, 2026, four days after it started. No playable build.", "requires": "No build to play. Contributors need an XCI dump of version 1.0.0 and the keys from their own console.", "inputFrom": "manual", "modManagerFrom": "manual", "cover": "assets/covers/xenoblade-chronicles-2-decomp.webp", "coverFrom": "wikipedia:Xenoblade Chronicles 2", "platforms": null, "platformsFrom": "manual", "platformsTag": null, "starsWeek": 0, "visitsWeek": 0}
